import{_ as t,o as s,c as a,ae as o}from"./chunks/framework.DQC_QtFV.js";const w=JSON.parse('{"title":"Conversations","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/console/conversations.md","filePath":"en/guide/console/conversations.md","lastUpdated":1793162416000}'),n={name:"en/guide/console/conversations.md"};function r(i,e,d,h,l,c){return s(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="conversations" tabindex="-1">Conversations <a class="header-anchor" href="#conversations" aria-label="Permalink to &quot;Conversations&quot;">​</a></h1><p>The conversations page answers one question: who does the assistant talk to. Its table lists the mirror&#39;s conversations, five columns each: name, type, <strong>状态</strong> (status), <strong>说话方式</strong> (how it speaks), and how many rules that row overrides. A change acts at once and the page keeps no save bar.</p><h2 id="状态-three-values-two-stores" tabindex="-1">状态: three values, two stores <a class="header-anchor" href="#状态-three-values-two-stores" aria-label="Permalink to &quot;状态: three values, two stores&quot;">​</a></h2><table tabindex="0"><thead><tr><th>状态</th><th>Meaning</th></tr></thead><tbody><tr><td>参与</td><td>the driver reads it and the bot is allowed to see it - it is read, and may be answered</td></tr><tr><td>只记录</td><td>the driver reads it and the panel shows it, but the bot does not see it - kept, silent</td></tr><tr><td>不读取</td><td>the driver drops it; the panel shows its name only</td></tr></tbody></table><p>One select writes both stores at the same time: the driver&#39;s scope and the bot&#39;s allow list, which is why &quot;allowed by the bot but outside the scope&quot; cannot be chosen. The scope mode is the 读取范围 card on <a href="./advanced.html">Advanced</a>; 不读取 is not offered while it reads 全部会话, and switching to 仅选中的会话 seeds the selection with what the driver reads today. Nothing is allowed by default: an empty allow list means the bot sees no conversation at all.</p><h2 id="说话方式-five-modes" tabindex="-1">说话方式: five modes <a class="header-anchor" href="#说话方式-five-modes" aria-label="Permalink to &quot;说话方式: five modes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Mode</th><th>Private</th><th>Group</th></tr></thead><tbody><tr><td>每条都回 (answer everything)</td><td>yes</td><td></td></tr><tr><td>只在被叫到时回 (only when addressed)</td><td>yes</td><td>yes</td></tr><tr><td>被叫到必回，其他时候看情况接话 (answer when addressed, otherwise maybe)</td><td></td><td>yes</td></tr><tr><td>全部看情况接话 (always a maybe)</td><td></td><td>yes</td></tr><tr><td>不说话 (silent)</td><td>yes</td><td>yes</td></tr></tbody></table><p>Addressed means: @ it, reply to its message, mention its nickname, or one of the aliases / keywords set below.</p><h2 id="the-three-switches" tabindex="-1">The three switches <a class="header-anchor" href="#the-three-switches" aria-label="Permalink to &quot;The three switches&quot;">​</a></h2><ul><li><strong>接收新消息</strong> (receive): off means new messages here no longer start a turn.</li><li><strong>允许发送</strong> (send): off means the bot cannot send into this conversation.</li><li><strong>允许被查阅</strong> (retrieve): off means the bot cannot see this history when it searches or writes notes in any conversation.</li></ul><p>With 接收 or 允许发送 off, 说话方式 is locked at 不说话 with the reason shown - a save never has to fail on the policy&#39;s dependency rule.</p><h2 id="看情况接话-joining-in-groups" tabindex="-1">看情况接话: joining in (groups) <a class="header-anchor" href="#看情况接话-joining-in-groups" aria-label="Permalink to &quot;看情况接话: joining in (groups)&quot;">​</a></h2><p>The block the two group modes unlock:</p><ul><li><strong>话痨度</strong> (talkativeness): a 0-3 slider; higher means it joins in more, and the time rules and the criterion below still govern it.</li><li><strong>按时段调整</strong> (time rules): scale talkativeness per <code>HH:MM</code> band with a 0-2 factor each; empty means no change all day.</li><li><strong>接话规矩</strong> (criterion): free text on when joining in fits and when it does not, which the judging model reads.</li></ul><p>Whether it joins is scored by <a href="https://typesafe.ai/" target="_blank" rel="noreferrer">Jev</a>; the stack subtracts a small penalty when the assistant has just been talking there, a little less when the batch @s it, and a batch aimed only at other people is left alone. After a few batches in a row where it stayed out, the next check waits longer - messages are held, not dropped - and an @, its name, a wake word or a burst of messages ends the delay at once.</p><h2 id="算作叫到我的词-words-that-count-as-addressing-it" tabindex="-1">算作叫到我的词: words that count as addressing it <a class="header-anchor" href="#算作叫到我的词-words-that-count-as-addressing-it" aria-label="Permalink to &quot;算作叫到我的词: words that count as addressing it&quot;">​</a></h2><p><strong>别名</strong> (aliases) and <strong>关键词</strong> (keywords), added with Enter, as many as you like.</p><h2 id="高级-two-jev-decisions" tabindex="-1">高级: two Jev decisions <a class="header-anchor" href="#高级-two-jev-decisions" aria-label="Permalink to &quot;高级: two Jev decisions&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Decision</th><th>What it decides</th><th>Threshold</th></tr></thead><tbody><tr><td>回复时机 (reply timing)</td><td>how long to wait for more messages before answering</td><td>0-2: the score at which waiting is worth it</td></tr><tr><td>引用 (quote)</td><td>whether a reply quotes the message it answers</td><td>0-1</td></tr></tbody></table><p>Each has three modes: <strong>关闭</strong> (never asked), <strong>只记录不生效</strong> (asked and logged, the rule default still acts - where every new decision ships), and <strong>启用</strong> (acts on the answer inside the rule&#39;s bounds). Besides the threshold each takes an optional 额外判断, your own extra criterion for that decision. 回复时机 also carries two caps, the most a private chat and a group may wait (30 s / 60 s by default); an @ or an admin waits at most 30 s.</p><h2 id="默认规则-and-one-conversation" tabindex="-1">默认规则 and one conversation <a class="header-anchor" href="#默认规则-and-one-conversation" aria-label="Permalink to &quot;默认规则 and one conversation&quot;">​</a></h2><p>The 默认规则 drawer holds the private and group templates plus the join-in question (threshold 0-1, the penalty ceiling 0-1, an optional criterion): a ceiling of 0 lets Jev alone decide. Clicking a conversation opens its drawer with four tabs:</p><ul><li><strong>规则</strong> (rules): every field above, marked 默认 or 覆盖 per row, with 恢复默认; an override stores only the fields it changes.</li><li><strong>消息</strong> (messages): the recent traffic, 打开全部 into the conversation&#39;s message sub-page.</li><li><strong>记录</strong> (records): this conversation&#39;s recent decisions and sends.</li><li><strong>唤醒词</strong> (wake words): read-only. The words a quiet end of turn left armed - any of them starts a new turn for six hours, and the next turn clears them.</li></ul>',23)])])}const u=t(n,[["render",r]]);export{w as __pageData,u as default};
